<section class="section narrow"><div class="eyebrow">TRACKING PESANAN</div><h1><?=h($order['order_code'])?></h1><div class="card"><div class="tracking-meta"><div><span>Kurir</span><b><?=h($order['shipping_method'])?></b></div><div><span>Estimasi</span><b><?=h($order['shipping_estimate']??'—')?></b></div><div><span>Tracking</span><b><?=h($order['tracking_number']?:'Menunggu dikirim')?></b></div></div><div class="timeline"><?php $steps=['waiting_payment'=>'Pesanan dibuat','paid'=>'Pembayaran berhasil','processing'=>'Diproses','quality_check'=>'Quality Check','packed'=>'Dikemas','shipped'=>'Dikirim','completed'=>'Selesai'];$status=array_keys($steps);$current=array_search($order['status'],$status,true);if($current===false)$current=0;foreach($steps as $k=>$label):$i=array_search($k,$status,true);?><div class="timeline-item <?=$i<=$current?'done':''?>"><span class="timeline-dot"></span><div><b><?=h($label)?></b><small><?=$i<=$current?'Sudah tercapai / berjalan':'Menunggu'?></small></div></div><?php endforeach;?></div></div></section>